    },
    "useCase": {
      "query": {
        "en": "Write a runbook for our auth service — alerts, dashboards, common procedures, on-call rotation.",
        "zh-CN": "使用这个插件完成以下任务：Write a runbook for our auth service — alerts, dashboards, common procedures, on-call rotation."
      },
      "exampleOutputs": [
        {
          "path": "./example.html",
          "title": "Eng Runbook"
        }
      ]
    },
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "designSystem": {
        "primary": true
      },
      "assets": [
        "./example.html"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "generate",
          "atoms": [
            "file-write",
            "live-artifact"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write"
    ]
  }
}
